// Why Code: valida y normaliza todos los campos de entrada en un solo paso
// (formato, día hábil, horario permitido, longitudes). Con nodos nativos
// serían 6+ IF/Set encadenados por campo.
const ZONA = 'America/Asuncion';
const HORARIOS = ['07:00', '08:00', '09:00', '10:00', '11:00', '13:00', '14:00', '15:00', '16:00', '17:00'];
const ahora = DateTime.now().setZone(ZONA);
const hoy = ahora.toISODate();
const e = $input.first().json;
const faltan = [];
const errores = [];
const txt = (v) => (v === undefined || v === null ? '' : String(v).trim());

function leerCedula(campo, requerido = true) {
  const v = txt(e[campo]).replace(/\D/g, '');
  if (!v) { if (requerido) faltan.push(campo); return ''; }
  if (v.length < 3 || v.length > 10) errores.push(`${campo}: debe tener entre 3 y 10 dígitos`);
  return v;
}

function leerFecha(campo, requerido = true) {
  let v = txt(e[campo]);
  if (!v) { if (requerido) faltan.push(campo); return ''; }
  const dmy = v.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
  if (dmy) v = `${dmy[3]}-${dmy[2].padStart(2, '0')}-${dmy[1].padStart(2, '0')}`;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(v) || !DateTime.fromISO(v, { zone: ZONA }).isValid) {
    errores.push(`${campo}: "${txt(e[campo])}" no es una fecha válida, usar YYYY-MM-DD`);
    return '';
  }
  return v;
}

function problemaDiaHabil(fecha) {
  if (!fecha) return '';
  const d = DateTime.fromISO(fecha, { zone: ZONA });
  if (fecha < hoy) return `la fecha ${fecha} ya pasó`;
  if (d.weekday > 5) return `el ${fecha} es ${d.setLocale('es').toFormat('cccc')} y solo se atiende de lunes a viernes`;
  return '';
}

function leerHora(campo, requerido = true) {
  const v = txt(e[campo]);
  if (!v) { if (requerido) faltan.push(campo); return ''; }
  const m = v.match(/^(\d{1,2})(?::(\d{2}))?(?::\d{2})?\s*(?:hs?)?$/i);
  const h = m ? `${m[1].padStart(2, '0')}:${m[2] || '00'}` : v;
  if (!HORARIOS.includes(h)) errores.push(`${campo}: "${v}" no es un horario de cita (${HORARIOS.join(', ')})`);
  return h;
}

function horaPasada(fecha, hora) {
  return fecha === hoy && hora && hora <= ahora.toFormat('HH:mm');
}

function leerArea(campo, requerido = true) {
  const v = txt(e[campo]).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  if (!v) { if (requerido) faltan.push(campo); return ''; }
  if (v.includes('soporte') || v.includes('manten')) return 'Soporte y Mantenimiento';
  if (v.includes('consult') || v.includes('general')) return 'Consultoría General';
  errores.push(`${campo}: área "${txt(e[campo])}" desconocida, usar "Consultoría General" o "Soporte y Mantenimiento"`);
  return '';
}

function leerTexto(campo, max, requerido = true) {
  const v = txt(e[campo]).replace(/[<>]/g, '').replace(/\s+/g, ' ');
  if (!v) { if (requerido) faltan.push(campo); return ''; }
  if (v.length > max) errores.push(`${campo}: máximo ${max} caracteres`);
  return v;
}

function leerTelefono(campo, requerido = true) {
  const v = txt(e[campo]).replace(/[^\d+]/g, '');
  if (!v) { if (requerido) faltan.push(campo); return ''; }
  if (v.length < 6 || v.length > 20) errores.push(`${campo}: teléfono inválido`);
  return v;
}

function leerCorreo(campo, requerido = true) {
  const v = txt(e[campo]).toLowerCase();
  if (!v) { if (requerido) faltan.push(campo); return ''; }
  if (v.length > 200 || !/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(v)) errores.push(`${campo}: correo inválido`);
  return v;
}

const masUnaHora = (h) => (h ? DateTime.fromFormat(h, 'HH:mm').plus({ hours: 1 }).toFormat('HH:mm') : '');
const legible = (f) => (f ? DateTime.fromISO(f, { zone: ZONA }).setLocale('es').toFormat("cccc d 'de' LLLL 'de' yyyy") : '');
const iso = (f, h, minutos = 0) => (f && h ? DateTime.fromISO(`${f}T${h}`, { zone: ZONA }).plus({ minutes: minutos }).toISO() : '');

function resultado(params, extra = {}) {
  const valido = faltan.length === 0 && errores.length === 0;
  const partes = [];
  if (faltan.length) partes.push('Faltan datos: ' + faltan.join(', '));
  if (errores.length) partes.push(errores.join('; '));
  return [{ json: {
    valido,
    codigo: valido ? 'ok' : 'datos_invalidos',
    mensaje: partes.join('. '),
    campos_faltantes: faltan,
    errores,
    params,
    ...extra,
    canal: txt(e.canal),
    session_id: txt(e.session_id),
    inicio: ahora.toISO(),
  } }];
}

// ----- validación específica de este workflow -----

const params = {
  cedula: leerCedula('cedula'),
  nombre: leerTexto('nombre', 100, false),
  apellido: leerTexto('apellido', 100, false),
  telefono: leerTelefono('telefono', false),
  direccion: leerTexto('direccion', 250, false),
  correo: leerCorreo('correo', false),
};
const cambios = Object.keys(params).filter((k) => k !== 'cedula' && params[k]);
if (!cambios.length) errores.push('no se indicó ningún dato para actualizar (nombre, apellido, telefono, direccion o correo)');
return resultado(params, { cambios });
